from pydantic import BaseModel
from typing import Optional

class DecisionOutput(BaseModel):
    decision: str
    penalty_usd: int
    rationale: str

shipment = get_shipment("SHP-900103")
contract = get_contract(shipment.vendor_id)
weather = get_weather_log(shipment.breach_date, shipment.hub_region)

query = f"""
You are an SLA compliance auditor. Analyze the following data and determine if the contract penalty is enforceable.

Shipment Details:
- Shipment ID: {shipment.shipment_id}
- Vendor ID: {shipment.vendor_id}
- Hub Region: {shipment.hub_region}
- Promised Date: {shipment.promised_date}
- Breach Date: {shipment.breach_date}
- Delay Days: {shipment.delay_days}

Contract Details:
- Vendor ID: {contract.vendor_id}
- Vendor Name: {contract.vendor_name}
- Clause Text: {contract.clause_text}
- Threshold Days: {contract.threshold_days}
- Penalty USD: {contract.penalty_usd}

Weather Log (on breach date at hub region):
- Log Date: {weather.log_date}
- Hub Region: {weather.hub_region}
- Wind Knots: {weather.wind_knots}
- Waiver Declared: {weather.waiver_declared}
- Event: {weather.event}

Instructions:
1. Determine if there is a breach: delay_days > threshold_days.
2. If no breach, decision is "NO_BREACH", penalty_usd is 0.
3. If breach exists, check contract clause for exceptions (e.g., force majeure, weather waivers).
4. Check weather log: if waiver_declared is true on breach date, penalty may be waived.
5. Apply every condition in the clause text.
6. Output decision: "ENFORCE", "WAIVE", or "NO_BREACH".
7. penalty_usd: contract.penalty_usd if ENFORCE, 0 otherwise.
8. rationale: one sentence explaining the decision.
"""

result = query_ai_assistant(query, DecisionOutput)
print(result.model_dump_json())
```

